if(!fs.existsSync(file))fs.writeFileSync(file,'{}');
const home=path.join(root,'home');fs.mkdirSync(home,{recursive:true});
function record(){const pending=[root],rows=[];while(pending.length){const name=pending.pop(),stat=fs.lstatSync(name,{bigint:true});if(stat.isSymbolicLink())throw new Error('Unexpected task link: '+name);rows.push({file:name,dev:String(stat.dev),ino:String(stat.ino),directory:stat.isDirectory()});if(stat.isDirectory())for(const child of fs.readdirSync(name))pending.push(path.join(name,child));}manifest.resources=rows;fs.writeFileSync(file,JSON.stringify(manifest,null,2));}
