 TMP:root,TEMP:root,TMPDIR:root,HOME:home,USERPROFILE:home,XDG_CONFIG_HOME:home,SP_CODING_AGENT_DIR:path.join(home,'agent'),SP_CODING_AGENT_SESSION_DIR:path.join(home,'sessions'),SP_OFFLINE:'1',SP_SKIP_VERSION_CHECK:'1',SP_TUI_WRITE_LOG:''};
const log=fs.openSync(path.join(root,label+'.log'),'wx');
const child=spawn(process.execPath,args,{cwd:path.resolve(root,'../..'),env,windowsHide:true,stdio:['ignore',log,log]});
